onClick:
{{
  (() => {
    const doc = new jspdf.jsPDF();
    let y = 15;
    doc.setFontSize(14);
    doc.text("Comentarios - Convocatoria " + appsmith.store.convocatoriaSeleccionada, 10, y);
    y += 10;
    doc.setFontSize(10);

    const preguntasExcluidas = [
      "Observaciones y comentarios sobre los aspectos t&eacute;cnicos de la Plataforma",
      "Observaciones y Comentarios sobre el Coordinador",
			"Observaciones y Comentarios sobre la interacci&oacute;n entre alumnos"
    ];

    comentariosCurso.data.forEach((item) => {
      const pregunta = item.pregunta.replace(/<[^>]*>/g, '').trim();
      const comentario = item.comentario.replace(/<[^>]*>/g, '');

      if (preguntasExcluidas.includes(pregunta)) return;

      if (y > 270) { doc.addPage(); y = 15; }

      doc.setFont(undefined, 'bold');
      const preguntaLines = doc.splitTextToSize(pregunta, 180);
      doc.text(preguntaLines, 10, y);
      y += preguntaLines.length * 5 + 2;

      doc.setFont(undefined, 'normal');
      const comentarioLines = doc.splitTextToSize(comentario, 180);
      doc.text(comentarioLines, 10, y);
      y += comentarioLines.length * 5 + 8;
    });

    const pdfDataUri = doc.output('datauristring');
    download(pdfDataUri, "comentarios_convocatoria_" + appsmith.store.convocatoriaSeleccionada + ".pdf", "application/pdf");
  })()
}}
